   "سندرم آنجلمن: خندهٔ نامتناسب، فقدان تکلم، آتاکسی و صرع — پاسخ صحیح.",
   "سندرم داون با تیپ چهره و تأخیر خفیف‌تر تظاهر دارد و خندهٔ مشخص ندارد.",
